import datetime
import unittest

try:
    from tests.helpers import CATALOG
except ImportError:
    from helpers import CATALOG
from stockroom.parsing import Movement, parse_catalog
from stockroom.shelves import format_delta, history, low_items, stock_levels, status

CAT = parse_catalog(CATALOG)


def mv(day, sku, qty):
    return Movement(datetime.date(2024, 3, day), sku, qty)


class ShelvesTest(unittest.TestCase):
    def test_stock_levels(self):
        moves = [mv(1, "AB-100", 20), mv(2, "AB-100", -3), mv(3, "CD-205", 40), mv(4, "CD-205", -40)]
        self.assertEqual(stock_levels(CAT, moves), {"AB-100": 17, "CD-205": 0, "EF-310": 0})
        self.assertEqual(stock_levels(CAT, []), {"AB-100": 0, "CD-205": 0, "EF-310": 0})

    def test_status(self):
        rows = [(0, 5, "out"), (0, 0, "out"), (1, 5, "low"), (5, 5, "low"), (6, 5, "ok"),
                (1, 0, "ok"), (100, 0, "ok"), (1, 1, "low")]
        for onhand, reorder, want in rows:
            with self.subTest(onhand=onhand, reorder=reorder):
                self.assertEqual(status(onhand, reorder), want)

    def test_low_items(self):
        cat = parse_catalog("ZZ-900|z|1|5\nAB-100|a|1|5\nCD-205|c|1|40\nEF-310|e|1|0\n"
                            "GH-400|g|1|5\nIJ-500|i|1|3\nKL-600|k|1|0\nMN-700|m|1|5")
        levels = {"ZZ-900": 5, "AB-100": 0, "CD-205": 17, "EF-310": 0, "GH-400": 6, "IJ-500": 100, "KL-600": 2,
                  "MN-700": 4}
        self.assertEqual(low_items(cat, levels), [
            ("AB-100", 0, 5, 10), ("CD-205", 17, 40, 63), ("EF-310", 0, 0, 1),
            ("MN-700", 4, 5, 6), ("ZZ-900", 5, 5, 5)])

    def test_low_items_from_stock_levels(self):
        levels = stock_levels(CAT, [mv(1, "AB-100", 20), mv(2, "CD-205", 41)])
        self.assertEqual(low_items(CAT, levels), [("EF-310", 0, 0, 1)])

    def test_history_in_counting_order(self):
        moves = [mv(5, "AB-100", -3), mv(1, "AB-100", 5), mv(3, "CD-205", 9), mv(5, "AB-100", 4),
                 mv(5, "AB-100", -1), mv(3, "AB-100", 2)]
        rows = history("AB-100", moves)
        self.assertEqual([(m.date.day, m.quantity, bal) for m, bal in rows],
                         [(1, 5, 5), (3, 2, 7), (5, -3, 4), (5, 4, 8), (5, -1, 7)])
        self.assertIs(rows[0][0], moves[1])
        self.assertEqual(history("EF-310", moves), [])
        self.assertEqual([m.sku for m, _ in history("CD-205", moves)], ["CD-205"])

    def test_format_delta(self):
        for q, want in [(20, "+20"), (-3, "-3"), (1, "+1"), (1000, "+1000"), (-1000, "-1000")]:
            self.assertEqual(format_delta(q), want)


if __name__ == "__main__":
    unittest.main()

